import{_ as i}from"./chunks/files.B17OUyrr.js";import{_ as r,c as a,o as s,a2 as t}from"./chunks/framework.CIiVzG-O.js";const h=JSON.parse('{"title":"Comparer des fichiers","description":"Ouvrez deux fichiers côte à côte, lisez les modifications codées par couleur, naviguez entre elles et modifiez ou partagez.","frontmatter":{"title":"Comparer des fichiers","description":"Ouvrez deux fichiers côte à côte, lisez les modifications codées par couleur, naviguez entre elles et modifiez ou partagez."},"headers":[],"relativePath":"fr/guide/files.md","filePath":"fr/guide/files.md","lastUpdated":1794296122000}'),o={name:"fr/guide/files.md"};function u(n,e,l,c,d,p){return s(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="comparer-des-fichiers" tabindex="-1">Comparer des fichiers <a class="header-anchor" href="#comparer-des-fichiers" aria-label="Permalink to &quot;Comparer des fichiers&quot;">​</a></h1><p>C&#39;est la vue par laquelle la plupart des gens commencent : deux versions du même fichier, côte à côte, avec chaque différence signalée.</p><img src="'+i+'" alt="Deux fichiers texte côte à côte avec des modifications en couleur" class="guide-shot"><h2 id="ouvrir-deux-fichiers" tabindex="-1">Ouvrir deux fichiers <a class="header-anchor" href="#ouvrir-deux-fichiers" aria-label="Permalink to &quot;Ouvrir deux fichiers&quot;">​</a></h2><p>Utilisez <strong>Fichier → Ouvrir</strong>, ou déposez simplement deux fichiers sur la fenêtre de qDiff. Besoin de rapprocher trois versions ? Ajoutez un troisième panneau — les mêmes règles de couleur s&#39;appliquent. Les comparaisons récentes sont conservées sur l&#39;écran d&#39;accueil pour la prochaine fois.</p><h2 id="ce-que-signifient-les-couleurs" tabindex="-1">Ce que signifient les couleurs <a class="header-anchor" href="#ce-que-signifient-les-couleurs" aria-label="Permalink to &quot;Ce que signifient les couleurs&quot;">​</a></h2><ul><li><strong>Rouge clair</strong> — le contenu de ce côté a été supprimé ou appartient à la version la plus ancienne.</li><li><strong>Vert clair</strong> — le contenu a été ajouté ou appartient à la version la plus récente.</li><li><strong>Couleur plus soutenue à l&#39;intérieur d&#39;une ligne</strong> — les mots exacts qui ont changé. Un seul mot modifié ne disparaît jamais dans une ligne entière colorée.</li></ul><p>Les deux côtés défilent ensemble, si bien que les deux versions restent toujours sur la même ligne.</p><h2 id="naviguer-entre-les-modifications" tabindex="-1">Naviguer entre les modifications <a class="header-anchor" href="#naviguer-entre-les-modifications" aria-label="Permalink to &quot;Naviguer entre les modifications&quot;">​</a></h2><p>Cliquez sur la fine carte à côté du texte pour aller n&#39;importe où dans le fichier, ou utilisez les boutons précédent / suivant (eux aussi dotés de raccourcis clavier) pour parcourir les modifications une par une. La carte indique également où vous en êtes dans un long document.</p><h2 id="corriger-au-fil-de-la-lecture" tabindex="-1">Corriger au fil de la lecture <a class="header-anchor" href="#corriger-au-fil-de-la-lecture" aria-label="Permalink to &quot;Corriger au fil de la lecture&quot;">​</a></h2><p>Chaque côté peut être modifié et annulé. Pour chaque modification, vous pouvez la copier de l&#39;autre côté, la remplacer ou la supprimer — directement depuis la comparaison, sans ouvrir un autre éditeur. Une fois terminé, enregistrez comme d&#39;habitude.</p><div class="tip custom-block"><p class="custom-block-title">Partager une image</p><p>Sélectionnez une modification et exportez-la en image : une image nette sur deux colonnes, facile à coller dans un message ou une revue. L&#39;image exportée ne comporte aucune marque.</p></div><p>Ensuite : <a href="./folders.html">comparez des dossiers entiers</a>.</p>',14)])])}const g=r(o,[["render",u]]);export{h as __pageData,g as default};
